    return _JsonParser(text).parse()


class _JsonParser:
    def __init__(self, text):
        self.text = text
        self.n = len(text)
        self.pos = 0

    def error(self):
        raise ValueError("malformed serialized model")

    def parse(self):
        value = self.parse_value()
        if self.pos != self.n:
            self.error()
        return value

    def parse_value(self):
        if self.pos >= self.n:
            self.error()
        char = self.text[self.pos]
        if char == "{":
            return self.parse_object()
        if char == "[":
            return self.parse_array()
        if char == '"':
            return self.parse_string_token()
        if char == "-" or "0" <= char <= "9":
            return self.parse_number_token()
        match = _JSON_LITERAL_RE.match(self.text, self.pos)
        if match is not None:
            literal = match.group(0)
            self.pos = match.end()
            if literal == "true":
                return True
            if literal == "false":
                return False
            return None
        self.error()

    def parse_object(self):
        pairs = _Object()
        self.pos += 1
        if self.pos < self.n and self.text[self.pos] == "}":
            self.pos += 1
            return pairs
        while True:
            if self.pos >= self.n or self.text[self.pos] != '"':
                self.error()
            key = self.parse_string_token()
            if self.pos >= self.n or self.text[self.pos] != ":":
                self.error()
            self.pos += 1
            value = self.parse_value()
            pairs.append((key, value))
            if self.pos >= self.n:
                self.error()
            if self.text[self.pos] == ",":
                self.pos += 1
                continue
            if self.text[self.pos] == "}":
                self.pos += 1
                break
            self.error()
        return pairs

    def parse_array(self):
        items = []
        self.pos += 1
        if self.pos < self.n and self.text[self.pos] == "]":
            self.pos += 1
            return items
        while True:
            items.append(self.parse_value())
            if self.pos >= self.n:
                self.error()
            if self.text[self.pos] == ",":
                self.pos += 1
                continue
            if self.text[self.pos] == "]":
                self.pos += 1
                break
            self.error()
        return items

    def parse_string_token(self):
        match = _JSON_STRING_RE.match(self.text, self.pos)
        if match is None:
            self.error()
        self.pos = match.end()
        return match.group(0)[1:-1]

    def parse_number_token(self):
        match = _JSON_NUMBER_RE.match(self.text, self.pos)
        if match is None:
            self.error()
        token = match.group(0)
        self.pos = match.end()
        if _JSON_INT_RE.match(token):
            return ("int", token)
        if _JSON_FLOAT_RE.match(token):
            return ("fixed", token)
        if _JSON_FLOAT12_RE.match(token):
            return ("fixed12", token)
        # Any other valid JSON numeric form (e.g. exponents) is not part of
        # the serialized byte format.
        self.error()


